{
  "name": "Gaijin Wheels - Your Car Partner in Japan",
  "description": "Specialized car dealership assistant for foreign residents in Japan. Offering local stock, Japanese finance calculations, and auction sheet translations.",
  "requestFramePermissions": [
    "camera"
