  { id: '1', make: 'Toyota', model: 'Prius', year: 2018, mileage: 45000, price: 1200000, image: 'https://picsum.photos/id/1071/800/600', transmission: 'AT', engine: '1.8L Hybrid', shaken: '2025/10' },
  { id: '2', make: 'Honda', model: 'N-Box', year: 2020, mileage: 12000, price: 950000, image: 'https://picsum.photos/id/183/800/600', transmission: 'AT', engine: '660cc', shaken: '2026/02' },
  { id: '3', make: 'Nissan', model: 'Serena', year: 2017, mileage: 68000, price: 1550000, image: 'https://picsum.photos/id/133/800/600', transmission: 'AT', engine: '2.0L Hybrid', shaken: '2025/05' },
];

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>(() => {
    const saved = localStorage.getItem('gaijin-wheels-lang');
    return (saved as Language) || Language.ES;
  });

  useEffect(() => {
    localStorage.setItem('gaijin-wheels-lang', lang);
    document.documentElement.dir = lang === Language.AR ? 'rtl' : 'ltr';
  }, [lang]);

  const t = translations[lang];

  return (
    <div className="min-h-screen bg-slate-50">
      <Navbar lang={lang} setLang={setLang} />

      <main className="pb-20">
        <Hero lang={lang} t={t} />

        <div id="inventory" className="max-w-7xl mx-auto px-4 py-16">
          <Inventory cars={MOCK_STOCK} t={t} lang={lang} />
        </div>

        <div id="finance" className="bg-white py-16 border-y border-slate-200">
          <div className="max-w-7xl mx-auto px-4">
            <FinanceCalculator t={t} lang={lang} />
          </div>
        </div>

        <div id="auction" className="max-w-7xl mx-auto px-4 py-16">
          <AuctionAnalyzer t={t} lang={lang} />
        </div>
      </main>

      <footer className="bg-slate-900 text-slate-400 py-12 px-4">
        <div className="max-w-7xl mx-auto grid grid-cols-1 md:grid-cols-3 gap-8 text-center md:text-left">
          <div>
            <h3 className="text-white text-xl font-bold mb-4">Gaijin Wheels</h3>
            <p>Empowering foreign residents in Japan with reliable mobility solutions since 2015.</p>
          </div>
          <div>
            <h4 className="text-white font-semibold mb-4">Quick Links</h4>
            <ul className="space-y-2">
              <li><a href="#inventory" className="hover:text-white transition">Stock</a></li>
              <li><a href="#finance" className="hover:text-white transition">Finance</a></li>
              <li><a href="#auction" className="hover:text-white transition">AI Auction</a></li>
            </ul>
          </div>
          <div>
            <h4 className="text-white font-semibold mb-4">Contact</h4>
            <p>Chiba-ken, Noda-shi, Japan</p>
            <p>support@gaijinwheels.jp</p>
          </div>
        </div>
        <div className="text-center mt-12 border-t border-slate-800 pt-8">
          <p>© 2024 Gaijin Wheels. All rights reserved. Registered Dealer #123456789</p>
        </div>
      </footer>

      <ChatBot lang={lang} />
      <WhatsAppButton lang={lang} t={t} />
    </div>
  );
};

export default App;

