import React, { useState, useEffect } from 'react';
import { VisaType, Language, FinanceResult } from '../types';

interface FinanceCalculatorProps {
  t: any;
  lang: Language;
}

const FinanceCalculator: React.FC<FinanceCalculatorProps> = ({ t }) => {
  const [price, setPrice] = useState(1500000);
  const [visa, setVisa] = useState<VisaType>(VisaType.PERMANENT);
  const [downPayment, setDownPayment] = useState(0);
  const [months, setMonths] = useState(36);
  const [result, setResult] = useState<FinanceResult | null>(null);

  const calculate = () => {
    let minDownRate = 0.1;
    let maxMonths = 60;

    if (visa === VisaType.WORK) {
      minDownRate = 0.2;
      maxMonths = Math.min(months, 36);
    } else if (visa === VisaType.STUDENT) {
      minDownRate = 0.5;
      maxMonths = Math.min(months, 24);
    }

    const minDown = price * minDownRate;
    const actualDown = Math.max(downPayment, minDown);
    const loanAmount = price - actualDown;
    const annualRate = 0.049; // 4.9% APR
    const monthlyRate = annualRate / 12;

    const monthlyPayment = loanAmount > 0 
      ? (loanAmount * monthlyRate * Math.pow(1 + monthlyRate, maxMonths)) / (Math.pow(1 + monthlyRate, maxMonths) - 1)
      : 0;

    setResult({
      monthlyPayment: Math.round(monthlyPayment),
      totalPayable: Math.round(monthlyPayment * maxMonths + actualDown),
      downPaymentRequired: Math.round(minDown),
      months: maxMonths
    });
  };

  useEffect(() => {
    calculate();
  }, [price, visa, downPayment, months]);

  return (
    <div className="bg-slate-50 rounded-3xl p-8 lg:p-12 shadow-inner border border-slate-200">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-start">
        <div className="space-y-8">
          <div>
            <h2 className="text-3xl font-bold text-slate-900 mb-2">{t.calcTitle}</h2>
            <p className="text-slate-600">{t.terms}</p>
          </div>

          <div className="space-y-6">
            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">{t.visaLabel}</label>
              <select 
                value={visa} 
                onChange={(e) => setVisa(e.target.value as VisaType)}
                className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 focus:ring-2 focus:ring-red-600 outline-none"
              >
                <option value={VisaType.PERMANENT}>Permanent / Long Term (10% Min)</option>
                <option value={VisaType.WORK}>Work / Spouse (20% Min)</option>
                <option value={VisaType.STUDENT}>Student (50% Min)</option>
              </select>
            </div>

            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">{t.priceLabel}</label>
              <input 
                type="range" min="500000" max="5000000" step="50000"
                value={price} onChange={(e) => setPrice(Number(e.target.value))}
                className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-red-600"
              />
              <div className="flex justify-between text-lg font-bold mt-2">
                <span>¥500k</span>
                <span className="text-red-600">¥{price.toLocaleString()}</span>
                <span>¥5M</span>
              </div>
            </div>

            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">{t.downLabel}</label>
              <input 
                type="number" 
                value={downPayment} 
                onChange={(e) => setDownPayment(Number(e.target.value))}
                className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 focus:ring-2 focus:ring-red-600 outline-none"
              />
              {result && downPayment < result.downPaymentRequired && (
                <p className="text-xs text-red-500 mt-1">Min. Required: ¥{result.downPaymentRequired.toLocaleString()}</p>
              )}
            </div>
          </div>
        </div>

        <div className="bg-white rounded-2xl p-8 border border-slate-200 shadow-xl">
          <h3 className="text-xl font-bold mb-6 text-slate-900">{t.results}</h3>

          <div className="space-y-6">
            <div className="pb-6 border-b border-slate-100">
              <p className="text-sm text-slate-500 mb-1">{t.monthly}</p>
              <div className="text-4xl font-black text-red-600">
                ¥{result?.monthlyPayment.toLocaleString()}
                <span className="text-base font-normal text-slate-400 ml-2">/ month</span>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <p className="text-xs text-slate-500 uppercase tracking-wider mb-1">Duration</p>
                <p className="font-bold text-slate-900">{result?.months} Months</p>
              </div>
              <div>
                <p className="text-xs text-slate-500 uppercase tracking-wider mb-1">{t.total}</p>
                <p className="font-bold text-slate-900">¥{result?.totalPayable.toLocaleString()}</p>
              </div>
            </div>

            <div className="bg-red-50 p-4 rounded-xl">
              <p className="text-xs text-red-800 leading-relaxed">
                * Based on 4.9% APR. Subject to credit check. Final price includes Name Transfer and Recycling Tax.
              </p>
            </div>

            <button className="w-full bg-red-600 hover:bg-red-700 text-white font-bold py-4 rounded-xl transition shadow-lg shadow-red-200">
              Apply Now
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FinanceCalculator;

import React, { useState } from 'react';
import { Language } from '../types';
import { analyzeAuctionSheet } from '../services/geminiService';

interface AuctionAnalyzerProps {
  t: any;
  lang: Language;
}

const AuctionAnalyzer: React.FC<AuctionAnalyzerProps> = ({ t, lang }) => {
  const [file, setFile] = useState<File | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [result, setResult] = useState<string | null>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      setFile(e.target.files[0]);
    }
  };

  const startAnalysis = async () => {
    if (!file) return;
    setAnalyzing(true);
    try {
      const analysis = await analyzeAuctionSheet(file, lang);
      setResult(analysis);
    } catch (error) {
      setResult("Error analyzing image. Please ensure it's a clear photo of an auction sheet.");
    } finally {
      setAnalyzing(false);
    }
  };

  return (
    <div className="bg-slate-900 rounded-3xl p-8 lg:p-12 text-white">
      <div className="max-w-3xl mx-auto text-center">
        <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-red-600 mb-6">
          <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
          </svg>
        </div>
        <h2 className="text-3xl font-bold mb-4">{t.auctionTitle}</h2>
        <p className="text-slate-400 mb-10">{t.auctionSub}</p>

        {!result ? (
          <div className="space-y-6">
            <div className="border-2 border-dashed border-slate-700 rounded-2xl p-10 bg-slate-800/50">
              <input 
                type="file" 
                id="auction-upload" 
                className="hidden" 
                onChange={handleFileChange}
                accept="image/*"
              />
              <label htmlFor="auction-upload" className="cursor-pointer group">
                <div className="mb-4 text-slate-500 group-hover:text-red-500 transition">
                  <svg className="w-12 h-12 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" />
                  </svg>
                </div>
                <p className="text-lg font-medium">{file ? file.name : "Select Auction Sheet Image"}</p>
                <p className="text-sm text-slate-500 mt-2">JPG, PNG or WEBP up to 5MB</p>
              </label>
            </div>

            {file && (
              <button 
                onClick={startAnalysis}
                disabled={analyzing}
                className={`w-full sm:w-auto px-8 py-4 rounded-xl font-bold transition ${analyzing ? 'bg-slate-700' : 'bg-red-600 hover:bg-red-700 shadow-xl shadow-red-900/40'}`}
              >
                {analyzing ? 'Analyzing with AI...' : 'Translate & Inspect'}
              </button>
            )}
          </div>
        ) : (
          <div className="text-left bg-slate-800 rounded-2xl p-8 border border-slate-700">
            <div className="prose prose-invert max-w-none">
              <h3 className="text-xl font-bold text-red-500 mb-4 flex items-center gap-2">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
                AI Analysis Results
              </h3>
              <div className="whitespace-pre-wrap text-slate-300 leading-relaxed">
                {result}
              </div>
            </div>
            <button 
              onClick={() => {setResult(null); setFile(null);}}
              className="mt-8 text-slate-500 hover:text-white transition underline"
            >
              Analyze another sheet
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default AuctionAnalyzer;

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Language } from '../types';

interface ChatBotProps {
  lang: Language;
}

const ChatBot: React.FC<ChatBotProps> = ({ lang }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{ role: 'user' | 'model'; text: string }[]>([
    { role: 'model', text: 'Kon' + (lang === Language.JP ? 'nichiwa!' : 'nichiwa! Welcome to Gaijin Wheels. I am your AI assistant. How can I help you find your dream car in Japan today?') }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const sendMessage = async () => {
    if (!input.trim() || loading) return;

    const userMessage = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const chat = ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: {
          systemInstruction: `You are "Gaijin Wheels", a virtual assistant for a car dealership in Japan specializing in foreign residents. 
          Your tone is professional, transparent, and very helpful. 
          PRIORITIES:
          1. Mention our own stock for immediate delivery if they ask for car suggestions.
          2. Final prices always include: Car Value + Recycling Tax + Name Transfer (Meigi Henko).
          3. Financing Rules: 
             - Permanent/Long-term: 10% down, up to 60 months.
             - Work/Spouse: 20% down, up to 36 months.
             - Student: 50% down.
          4. Auction Analysis: Explain Grades S, 5, 4.5 are top. R/RA are repaired. Avoid S2/S3 (rust).
          Current language of the UI is ${lang}. Please respond primarily in ${lang} but you can use Japanese terms (like Shaken, Meigi Henko) where appropriate.`
        }
      });

      const response = await chat.sendMessage({ message: userMessage });
      setMessages(prev => [...prev, { role: 'model', text: response.text || 'Sorry, I encountered an error.' }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: 'I am sorry, my connection to the server was interrupted. Please try again later.' }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed bottom-24 right-6 z-50 flex flex-col items-end">
      {isOpen && (
        <div className="bg-white w-80 sm:w-96 h-[500px] rounded-2xl shadow-2xl border border-slate-200 flex flex-col mb-4 overflow-hidden animate-in slide-in-from-bottom-5 duration-300">
          <div className="bg-red-600 p-4 text-white flex justify-between items-center">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 bg-white rounded-full flex items-center justify-center text-red-600 font-bold text-xs">GW</div>
              <span className="font-bold">Gaijin Wheels AI</span>
            </div>
            <button onClick={() => setIsOpen(false)} className="hover:bg-red-700 rounded-lg p-1">
