import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { Language } from '../types';

export const analyzeAuctionSheet = async (file: File, lang: Language): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const base64Data = await fileToBase64(file);
  const imagePart = {
    inlineData: {
      mimeType: file.type,
      data: base64Data,
    },
  };

  const prompt = `Analyze this Japanese car auction sheet. 
  1. Identify the auction grade (e.g., S, 5, 4.5, 4, 3, R, RA).
  2. Look for damage codes: A (scratches), U (dents), W (repairs), S (rust/corrosion).
  3. Tell me if the car is in good condition (Grade 4+ is good, S/5 is excellent).
  4. Specifically warn if there is S2 or S3 (serious rust).
  5. Translate key info (Year, Model, Mileage) to ${lang}.
  6. Give a final "Buy or Skip" recommendation based on typical Japanese market standards for foreigners.
  Be honest and transparent. Provide the response in ${lang}.`;

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: 'gemini-3-pro-preview', 
    contents: { parts: [imagePart, { text: prompt }] },
  });

  return response.text || "Could not extract information.";
};

export interface MarketSearchResponse {
  text: string;
  sources: { title: string; uri: string }[];
  imageUrl?: string;
}

export const searchLiveMarket = async (query: string, lang: Language, latLng?: { latitude: number; longitude: number }): Promise<MarketSearchResponse> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Step 1: Real-time Search Grounding with Visual Extraction
  const searchPrompt = `Act as Gaijin Wheels Auction Agent. 
  Search for real-time market data in Japan for: "${query}".
  Include:
  1. Average winning bids at auctions (USS, JAA, etc.) for this exact year and model.
  2. Current availability in popular dealerships (Goo-net, Carsensor).
  3. IMPORTANT: Describe the visual appearance of this SPECIFIC GENERATION (e.g. headlight shape, grill type, body style for the year ${query}).
  Provide result in ${lang}. 
  IMPORTANT: Only use real data from the web. Focus on the era-appropriate features.`;

  const searchResponse: GenerateContentResponse = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: searchPrompt,
    config: {
      tools: [{ googleSearch: {} }],
    },
  });

  const sources = searchResponse.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
    title: chunk.web?.title || 'Auction Source',
    uri: chunk.web?.uri || '#'
  })) || [];

  // Step 2: Image Generation with strict generation/year constraints
  let imageUrl = undefined;
  try {
    const textContent = searchResponse.text;
    // We create a very specific prompt that forbids "modern" elements for older cars
    const imagePrompt = `PHOTOGRAPH of the car: ${query}. 
    STRICT RULE: This car MUST be the exact version/generation from the year mentioned in the query. 
    IF THE CAR IS FROM 2001 or older: Do NOT use modern LED lights, do NOT use modern aerodynamic curves, use period-correct wheels and trim.
    IF THE SEARCH RESULTS mention specific features like "${textContent.substring(0, 150)}", include them.
    Style: Real-life car listing photo from a Japanese dealership parking lot (Goo-net style), high resolution, realistic textures, daylight. 
    NO modern 2024 design elements. Accurate body shape for the year ${query}.`;

    const imageResponse = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: imagePrompt }] },
      config: {
        imageConfig: { aspectRatio: "16:9" }
      }
    });

    for (const part of imageResponse.candidates[0].content.parts) {
      if (part.inlineData) {
        imageUrl = `data:image/png;base64,${part.inlineData.data}`;
        break;
      }
    }
  } catch (imgError) {
    console.warn("Failed to generate preview image:", imgError);
  }

  return {
    text: searchResponse.text || "No results found.",
    sources: sources.filter((s, idx, self) => idx === self.findIndex(t => t.uri === s.uri)),
    imageUrl
  };
};

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const base64 = (reader.result as string).split(',')[1];
      resolve(base64);
    };
    reader.onerror = (error) => reject(error);
  });
};

