import React, { useState } from 'react';
import { Car, Language } from '../types';
import { calculateCarLoan } from '../utils/finance';

interface InventoryProps {
  cars: Car[];
  t: any;
  lang: Language;
}

const Inventory: React.FC<InventoryProps> = ({ cars, t }) => {
  const [selectedCar, setSelectedCar] = useState<Car | null>(null);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);

  const estimateMonthly = (price: number) => {
    const calc = calculateCarLoan({
      carPrice: price,
      downPayment: price * 0.2,
      visaType: 'permanent' as any,
      requestedMonths: 36
    });
    return calc.monthlyPayment;
  };

  const openGallery = (car: Car) => {
    setSelectedCar(car);
    setCurrentImageIndex(0);
  };

  const nextImage = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!selectedCar?.gallery) return;
    setCurrentImageIndex((prev) => (prev + 1) % (selectedCar.gallery?.length || 1));
  };

  const prevImage = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!selectedCar?.gallery) return;
    setCurrentImageIndex((prev) => (prev - 1 + (selectedCar.gallery?.length || 1)) % (selectedCar.gallery?.length || 1));
  };

  return (
    <section>
      <div className="text-center mb-12">
        <h2 className="text-3xl md:text-5xl font-black text-slate-900 mb-4">{t.stockTitle}</h2>
        <p className="text-slate-600 text-lg max-w-2xl mx-auto">{t.stockSub}</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {cars.map((car) => (
          <div key={car.id} className="group bg-white rounded-3xl border border-slate-200 overflow-hidden hover:shadow-2xl transition-all duration-500 hover:-translate-y-1">
            <div className="relative h-64 overflow-hidden cursor-pointer" onClick={() => openGallery(car)}>
              <img 
                src={car.image} 
                alt={`${car.make} ${car.model}`} 
                className="w-full h-full object-cover group-hover:scale-110 transition duration-700"
              />
              <div className="absolute top-4 left-4 bg-red-600 text-white text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-[0.2em]">
                {t.immediateDelivery}
              </div>
              <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                 <div className="bg-white/90 p-3 rounded-full text-slate-900 shadow-xl">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0zM10 7v3m0 0v3m0-3h3m-3 0H7" /></svg>
                 </div>
              </div>
              <div className="absolute bottom-4 right-4 bg-white/90 backdrop-blur-sm px-4 py-2 rounded-2xl shadow-lg">
                <p className="text-[10px] text-slate-500 uppercase font-bold tracking-wider mb-0.5">{t.startingFrom}</p>
                <p className="text-red-600 font-black text-lg leading-none">
                  ¥{estimateMonthly(car.price).toLocaleString()}<span className="text-xs font-medium text-slate-400 ml-1">{t.perMonth}</span>
                </p>
              </div>
            </div>

            <div className="p-6">
              <div className="flex justify-between items-end mb-6">
                <div>
                  <h3 className="text-2xl font-black text-slate-900 leading-tight">{car.make} {car.model}</h3>
                  <p className="text-slate-400 text-sm">{car.year} • {car.engine}</p>
                </div>
                <div className="text-right">
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Base Price</p>
                  <p className="text-slate-900 font-black text-xl">¥{car.price.toLocaleString()}</p>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4 mb-8">
                <div className="bg-slate-50 p-3 rounded-2xl">
                  <p className="text-[10px] text-slate-400 font-bold uppercase mb-1">Mileage</p>
                  <p className="text-slate-900 font-bold">{car.mileage.toLocaleString()} km</p>
                </div>
                <div className="bg-slate-50 p-3 rounded-2xl">
                  <p className="text-[10px] text-slate-400 font-bold uppercase mb-1">Shaken</p>
                  <p className="text-slate-900 font-bold">{car.shaken}</p>
                </div>
              </div>

              <button onClick={() => openGallery(car)} className="w-full bg-slate-900 hover:bg-red-600 text-white font-bold py-4 rounded-2xl transition-all duration-300 flex items-center justify-center gap-2 group/btn">
                <span>{t.details}</span>
                <svg className="w-4 h-4 group-hover/btn:translate-x-1 transition" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7" />
                </svg>
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* Lightbox Modal */}
      {selectedCar && (
        <div className="fixed inset-0 z-[120] bg-slate-950/95 backdrop-blur-xl flex flex-col animate-in fade-in duration-300 overflow-hidden">
           <div className="flex justify-between items-center p-6 text-white">
              <div>
                <h3 className="text-xl font-black">{selectedCar.make} {selectedCar.model}</h3>
                <p className="text-xs text-slate-400 uppercase font-black tracking-widest">Image {currentImageIndex + 1} of {selectedCar.gallery?.length || 1}</p>
              </div>
              <button 
                onClick={() => setSelectedCar(null)}
                className="bg-white/10 hover:bg-white/20 p-3 rounded-full transition"
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
           </div>

           <div className="flex-1 relative flex items-center justify-center px-4">
              <button onClick={prevImage} className="absolute left-4 z-10 bg-black/40 hover:bg-red-600 text-white p-5 rounded-full transition">
                <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M15 19l-7-7 7-7" /></svg>
              </button>

              <div className="max-w-6xl w-full h-full flex items-center justify-center">
                 <img 
                    src={selectedCar.gallery ? selectedCar.gallery[currentImageIndex] : selectedCar.image} 
                    className="max-h-full max-w-full object-contain rounded-2xl shadow-2xl animate-in zoom-in-95 duration-500"
                    alt="Gallery View"
                 />
              </div>

              <button onClick={nextImage} className="absolute right-4 z-10 bg-black/40 hover:bg-red-600 text-white p-5 rounded-full transition">
                <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7" /></svg>
              </button>
           </div>

           <div className="p-8 flex justify-center gap-2 overflow-x-auto custom-scrollbar">
              {selectedCar.gallery?.map((img, idx) => (
                <button 
                  key={idx}
                  onClick={() => setCurrentImageIndex(idx)}
                  className={`w-20 h-20 rounded-xl overflow-hidden border-2 transition-all ${currentImageIndex === idx ? 'border-red-600 scale-110' : 'border-transparent opacity-50 hover:opacity-100'}`}
                >
                  <img src={img} className="w-full h-full object-cover" alt={`Thumb ${idx}`} />
                </button>
              ))}
           </div>
        </div>
      )}
    </section>
  );
};

export default Inventory;

