            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-12">
              {[
                { id: '1d', label: t.plan1Day, price: '¥500', desc: 'Short-term search' },
                { id: '1w', label: t.plan1Week, price: '¥2,000', desc: 'Active hunter pass', popular: true },
                { id: '1m', label: t.plan1Month, price: '¥4,000', desc: 'Professional Dealer Access' },
              ].map((plan) => (
                <button 
                  key={plan.id}
                  onClick={() => setSelectedPlan(plan.id)}
                  className={`relative p-8 rounded-[2.5rem] border-2 text-left transition-all duration-300 transform ${
                    selectedPlan === plan.id 
                      ? 'border-red-600 bg-red-50/50 -translate-y-2 ring-4 ring-red-600/10' 
                      : 'border-slate-100 bg-white hover:border-slate-200 shadow-sm'
                  }`}
                >
                  {plan.popular && (
                    <div className="absolute -top-3 left-1/2 -translate-x-1/2 bg-red-600 text-white text-[8px] font-black uppercase tracking-widest px-4 py-1.5 rounded-full shadow-lg">
                      BEST VALUE
                    </div>
                  )}
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">{plan.desc}</p>
                  <p className="text-xl font-black text-slate-900 mb-1 leading-none">{plan.label.split(' (')[0]}</p>
                  <p className="text-3xl font-black text-red-600">{plan.price}</p>
                  <div className={`mt-6 w-full h-2 rounded-full ${selectedPlan === plan.id ? 'bg-red-600 animate-pulse' : 'bg-slate-100'}`}></div>
                </button>
              ))}
            </div>

            <button 
              onClick={simulatePayment}
              disabled={processing || !selectedPlan}
              className="w-full bg-slate-900 text-white font-black px-16 py-6 rounded-2xl shadow-2xl hover:bg-red-600 transition-all duration-300 disabled:opacity-50 flex items-center justify-center gap-4 text-lg"
            >
              {processing ? 'Verifying Access...' : t.payToView}
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

