import React, { useState } from 'react';
import { Car, Language } from '../types';

interface AdminPanelProps {
  onAddCar: (car: Car) => void;
  t: any;
  lang: Language;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onAddCar, t }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    make: '',
    model: '',
    year: new Date().getFullYear(),
    mileage: '',
    price: '',
    engine: '660cc',
    shaken: '',
    transmission: 'AT' as 'AT' | 'MT'
  });
  const [images, setImages] = useState<string[]>([]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      setLoading(true);
      const files = Array.from(e.target.files);
      const base64Promises = files.map(file => {
        return new Promise<string>((resolve) => {
          const reader = new FileReader();
          reader.onloadend = () => resolve(reader.result as string);
          reader.readAsDataURL(file);
        });
      });
      const base64Images = await Promise.all(base64Promises);
      setImages(prev => [...prev, ...base64Images]);
      setLoading(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (images.length === 0) return alert("Carga al menos una foto");

    const newCar: Car = {
      id: `custom-${Date.now()}`,
      make: formData.make,
      model: formData.model,
      year: Number(formData.year),
      mileage: Number(formData.mileage),
      price: Number(formData.price),
      image: images[0],
      gallery: images,
      transmission: formData.transmission,
      engine: formData.engine,
      shaken: formData.shaken
    };

    onAddCar(newCar);
    setIsOpen(false);
    // Reset form
    setFormData({ make: '', model: '', year: 2024, mileage: '', price: '', engine: '660cc', shaken: '', transmission: 'AT' });
    setImages([]);
  };

  return (
    <>
      <button 
        onClick={() => setIsOpen(true)}
        className="fixed bottom-6 left-6 z-50 bg-slate-900 text-white p-4 rounded-full shadow-2xl hover:bg-red-600 transition-all border border-slate-700 flex items-center gap-2 group"
