           <div className="flex-1 relative flex items-center justify-center px-2 sm:px-12 py-4">
              <button onClick={prevImage} className="hidden sm:flex absolute left-8 z-10 bg-white/5 hover:bg-red-600 text-white p-6 rounded-full transition-all duration-300 backdrop-blur-md border border-white/10">
                <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M15 19l-7-7 7-7" /></svg>
