                  key={idx}
                  onClick={() => setCurrentImageIndex(idx)}
                  className={`w-16 h-16 sm:w-24 sm:h-24 rounded-2xl overflow-hidden border-4 transition-all duration-300 shrink-0 ${currentImageIndex === idx ? 'border-red-600 scale-110 shadow-lg' : 'border-transparent opacity-40 hover:opacity-100'}`}
