                  <img src={img} className="w-full h-full object-cover" alt={`Thumb ${idx}`} onError={(e) => { (e.target as HTMLImageElement).src = 'https://images.unsplash.com/photo-1542362567-b0526019665a?q=80&w=200'; }} />
                </button>
              ))}
           </div>
        </div>
      )}
    </section>
  );
};

