import React, { useState } from 'react';
import { Car, Language } from '../types';

interface AdminPanelProps {
  onAddCar: (car: Car) => void;
  t: any;
  lang: Language;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onAddCar, t }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    make: '',
    model: '',
    year: new Date().getFullYear(),
    mileage: '',
    price: '',
    engine: '660cc',
    shaken: '',
    transmission: 'AT' as 'AT' | 'MT'
  });
  const [images, setImages] = useState<string[]>([]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      setLoading(true);
      // Fix: Added explicit type cast to File[] to resolve 'unknown' error
      const files = Array.from(e.target.files) as File[];
      const base64Promises = files.map(file => {
        return new Promise<string>((resolve) => {
          const reader = new FileReader();
          reader.onloadend = () => resolve(reader.result as string);
          reader.readAsDataURL(file);
        });
      });
      const base64Images = await Promise.all(base64Promises);
      setImages(prev => [...prev, ...base64Images]);
      setLoading(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (images.length === 0) return alert("Carga al menos una foto");

    const newCar: Car = {
      id: `custom-${Date.now()}`,
      make: formData.make,
      model: formData.model,
      year: Number(formData.year),
      mileage: Number(formData.mileage),
      price: Number(formData.price),
      image: images[0],
      gallery: images,
      transmission: formData.transmission,
      engine: formData.engine,
      shaken: formData.shaken
    };

    onAddCar(newCar);
    setIsOpen(false);
    // Reset form
    setFormData({ make: '', model: '', year: 2024, mileage: '', price: '', engine: '660cc', shaken: '', transmission: 'AT' });
    setImages([]);
  };

  return (
    <>
      <button 
        onClick={() => setIsOpen(true)}
        className="fixed bottom-6 left-6 z-50 bg-slate-900 text-white p-4 rounded-full shadow-2xl hover:bg-red-600 transition-all border border-slate-700 flex items-center gap-2 group"
      >
        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
        <span className="max-w-0 overflow-hidden group-hover:max-w-xs transition-all duration-500 font-bold whitespace-nowrap">Gestionar Stock</span>
      </button>

      {isOpen && (
        <div className="fixed inset-0 z-[200] bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4 animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-2xl rounded-[3rem] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50">
              <div>
                <h2 className="text-2xl font-black text-slate-900">Agregar Nueva Unidad</h2>
                <p className="text-slate-500 text-sm">Carga tus fotos y datos del vehículo</p>
              </div>
              <button onClick={() => setIsOpen(false)} className="bg-white p-2 rounded-full shadow-sm hover:text-red-600">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-8 overflow-y-auto space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Marca</label>
                  <input required value={formData.make} onChange={e => setFormData({...formData, make: e.target.value})} className="w-full bg-slate-100 p-4 rounded-2xl outline-none focus:ring-2 focus:ring-red-600/20" placeholder="Ej: Toyota" />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Modelo</label>
                  <input required value={formData.model} onChange={e => setFormData({...formData, model: e.target.value})} className="w-full bg-slate-100 p-4 rounded-2xl outline-none focus:ring-2 focus:ring-red-600/20" placeholder="Ej: Prius" />
                </div>
              </div>

              <div className="grid grid-cols-3 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Año</label>
                  <input type="number" required value={formData.year} onChange={e => setFormData({...formData, year: Number(e.target.value)})} className="w-full bg-slate-100 p-4 rounded-2xl outline-none" />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Precio (JPY)</label>
                  <input type="number" required value={formData.price} onChange={e => setFormData({...formData, price: e.target.value})} className="w-full bg-slate-100 p-4 rounded-2xl outline-none" placeholder="780000" />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">KM</label>
                  <input type="number" required value={formData.mileage} onChange={e => setFormData({...formData, mileage: e.target.value})} className="w-full bg-slate-100 p-4 rounded-2xl outline-none" placeholder="58000" />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                 <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Shaken (Fecha)</label>
                  <input required value={formData.shaken} onChange={e => setFormData({...formData, shaken: e.target.value})} className="w-full bg-slate-100 p-4 rounded-2xl outline-none" placeholder="2026/03" />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Motor / Transmisión</label>
                  <div className="flex gap-2">
                    <input value={formData.engine} onChange={e => setFormData({...formData, engine: e.target.value})} className="flex-1 bg-slate-100 p-4 rounded-2xl outline-none" placeholder="660cc" />
                    <select value={formData.transmission} onChange={e => setFormData({...formData, transmission: e.target.value as any})} className="bg-slate-100 p-4 rounded-2xl outline-none">
                      <option value="AT">AT</option>
                      <option value="MT">MT</option>
                    </select>
                  </div>
                </div>
              </div>

              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest block">Fotos de la Unidad</label>
                <div className="grid grid-cols-4 gap-2">
                  {images.map((img, i) => (
                    <div key={i} className="aspect-square rounded-xl overflow-hidden relative border border-slate-200">
                      <img src={img} className="w-full h-full object-cover" />
                      <button type="button" onClick={() => setImages(images.filter((_, idx) => idx !== i))} className="absolute top-1 right-1 bg-red-600 text-white rounded-full p-1">
                        <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12" /></svg>
                      </button>
                    </div>
                  ))}
                  <label className="aspect-square rounded-xl border-2 border-dashed border-slate-300 flex flex-col items-center justify-center cursor-pointer hover:border-red-600 hover:bg-red-50 transition">
                    <input type="file" multiple accept="image/*" onChange={handleFileChange} className="hidden" />
                    <svg className="w-6 h-6 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
                    <span className="text-[8px] font-black uppercase mt-1">Cargar</span>
                  </label>
                </div>
              </div>

              <button 
                type="submit" 
                disabled={loading}
                className="w-full bg-red-600 text-white font-black py-5 rounded-2xl shadow-xl shadow-red-600/20 hover:bg-slate-900 transition-all text-lg"
              >
                {loading ? 'Procesando imágenes...' : 'Publicar en Inventario'}
              </button>
