import React, { useState } from 'react';
import { Car, Language } from '../types';

interface AdminPanelProps {
  onAddCar: (car: Car) => void;
  t: any;
  lang: Language;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onAddCar, t }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [driveLink, setDriveLink] = useState('');
  const [formData, setFormData] = useState({
    make: '',
    model: '',
    year: new Date().getFullYear(),
    mileage: '',
    price: '',
    engine: '660cc',
    shaken: '',
    transmission: 'AT' as 'AT' | 'MT'
  });
  const [images, setImages] = useState<string[]>([]);

  // Función para convertir enlaces de Google Drive en enlaces de imagen directa
  const transformDriveLink = (link: string) => {
    const driveRegex = /(?:https?:\/\/)?(?:drive\.google\.com\/(?:file\/d\/|open\?id=)|googledrive\.com\/host\/)([a-zA-Z0-0_-]+)/;
    const match = link.match(driveRegex);
    if (match && match[1]) {
      return `https://drive.google.com/uc?export=view&id=${match[1]}`;
    }
    return link; // Si no es de Drive, devolvemos el link original (asumiendo que es una URL directa)
  };

  const handleAddDriveLink = () => {
    if (!driveLink.trim()) return;
    const directLink = transformDriveLink(driveLink);
    setImages(prev => [...prev, directLink]);
    setDriveLink('');
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      setLoading(true);
      const files = Array.from(e.target.files) as File[];
      const base64Promises = files.map(file => {
        return new Promise<string>((resolve) => {
          const reader = new FileReader();
          reader.onloadend = () => resolve(reader.result as string);
          reader.readAsDataURL(file);
        });
      });
      const base64Images = await Promise.all(base64Promises);
      setImages(prev => [...prev, ...base64Images]);
      setLoading(false);
    }
