   * 2. Filtramos enlaces de "folders" (carpetas). Drive no permite ver fotos de una carpeta sin API Key.
   * 3. Educamos al usuario: debe seleccionar las FOTOS, no la CARPETA.
   */
  const processBulkLinks = () => {
    if (!bulkLinks.trim()) return;

    // Detectamos si el usuario pegó un link de carpeta por error
    if (bulkLinks.includes('/drive/folders/') && !bulkLinks.includes('file/d/')) {
      alert("⚠️ Has pegado un enlace de CARPETA. \n\nPara que funcione: Entra a la carpeta en Drive, selecciona todas las fotos, haz clic derecho -> Compartir -> Copiar enlaces, y pega ESO aquí.");
      return;
    }

    // Regex mejorado para capturar solo IDs de ARCHIVOS
    const driveIdRegex = /(?:file\/d\/|id=)([a-zA-Z0-9_-]{25,})[/?]?/g;
    let match;
    const foundIds: string[] = [];

    while ((match = driveIdRegex.exec(bulkLinks)) !== null) {
      if (match[1]) {
        // Usamos el endpoint de thumbnail con alta resolución (sz=w1200) para evitar bloqueos de visualización
        foundIds.push(`https://drive.google.com/thumbnail?id=${match[1]}&sz=w1200`);
      }
    }

    if (foundIds.length > 0) {
      // Evitamos duplicados
      const uniqueNewLinks = foundIds.filter(link => !images.includes(link));
      setImages(prev => [...prev, ...uniqueNewLinks]);
      setBulkLinks('');
    } else {
      alert("No se detectaron fotos válidas. Asegúrate de copiar los enlaces de los ARCHIVOS (fotos) y no de la carpeta completa.");
    }
