                />
                <button 
                  type="button"
                  onClick={processBulkLinks}
                  className="w-full bg-blue-600 text-white py-4 rounded-xl font-black text-sm hover:bg-blue-700 transition shadow-lg shadow-blue-200 flex items-center justify-center gap-2"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                  Extraer Fotos de Drive
                </button>
                <div className="p-3 bg-white/50 rounded-xl border border-blue-100 mt-2">
                   <p className="text-[10px] text-blue-600 font-bold leading-tight">
                     💡 IMPORTANTE: Asegúrate de que los archivos en Drive tengan el acceso en "Cualquier persona con el enlace". Si son privados, verás 'Error Link'.
                   </p>
                </div>
              </div>

              {/* GALERÍA DE PREVISUALIZACIÓN */}
