                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12" /></svg>
                        </button>
                      </div>
                      {img.includes('google.com') && (
                         <div className="absolute top-1 left-1 bg-blue-600 text-[6px] text-white px-1 py-0.5 rounded font-black shadow-sm">DRIVE</div>
                      )}
                    </div>
                  ))}
                  {images.length === 0 && (
                    <div className="col-span-full py-10 border-2 border-dashed border-slate-100 rounded-2xl flex flex-col items-center justify-center text-slate-300">
                       <svg className="w-8 h-8 mb-2 opacity-30" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                       <p className="text-[10px] font-bold uppercase tracking-widest">Esperando fotos...</p>
                    </div>
                  )}
                </div>
              </div>

              <button 
                type="submit" 
                disabled={loading || images.length === 0}
                className="w-full bg-slate-900 text-white font-black py-5 rounded-3xl shadow-xl hover:bg-red-600 transition-all text-lg disabled:opacity-50 disabled:hover:bg-slate-900"
              >
                {loading ? 'Subiendo...' : 'Publicar Ahora'}
              </button>
            </form>
          </div>
        </div>
      )}
    </>
  );
};

