const App: React.FC = () => {
  const [lang, setLang] = useState<Language | null>(() => {
    const saved = localStorage.getItem('gaijin-wheels-lang');
    return (saved as Language) || null;
  });

  const [cars, setCars] = useState<Car[]>(() => {
    const savedCars = localStorage.getItem('gw-custom-stock');
    if (savedCars) {
      // Unimos los guardados con los iniciales, evitando duplicar por ID
      const parsed = JSON.parse(savedCars) as Car[];
      const initialFiltered = INITIAL_STOCK.filter(ic => !parsed.find(pc => pc.id === ic.id));
      return [...parsed, ...initialFiltered];
    }
    return INITIAL_STOCK;
  });

  const [showLangModal, setShowLangModal] = useState(!lang);
  const [carToEdit, setCarToEdit] = useState<Car | null>(null);

  useEffect(() => {
    if (lang) {
      localStorage.setItem('gaijin-wheels-lang', lang);
      document.documentElement.dir = lang === Language.AR ? 'rtl' : 'ltr';
      document.documentElement.lang = lang;
    }
  }, [lang]);

  const handleLangSelect = (selectedLang: Language) => {
    setLang(selectedLang);
    setShowLangModal(false);
  };

  const saveToStorage = (updatedList: Car[]) => {
    // Solo guardamos los que tienen ID de custom para no inflar el storage con los iniciales (opcional)
    // O guardamos todo si queremos permitir editar los iniciales también.
    localStorage.setItem('gw-custom-stock', JSON.stringify(updatedList));
  };

  const handleAddCar = (newCar: Car) => {
    const updatedCars = [newCar, ...cars];
    setCars(updatedCars);
    saveToStorage(updatedCars);
  };

  const handleEditCar = (updatedCar: Car) => {
    const updatedCars = cars.map(c => c.id === updatedCar.id ? updatedCar : c);
    setCars(updatedCars);
    saveToStorage(updatedCars);
    setCarToEdit(null);
  };

  const handleDeleteCar = (id: string) => {
    const updatedCars = cars.filter(c => c.id !== id);
    setCars(updatedCars);
    saveToStorage(updatedCars);
  };

  const currentLang = lang || Language.EN;
  const t = translations[currentLang] || translations[Language.EN];

  return (
    <div className={`min-h-screen bg-slate-50 ${showLangModal ? 'overflow-hidden h-screen' : ''}`}>
