            t={t} 
            lang={currentLang} 
            onDelete={handleDeleteCar} 
            onEdit={(car) => setCarToEdit(car)}
          />
        </div>

        <AdminPanel 
          onAddCar={handleAddCar} 
          onEditCar={handleEditCar}
          editingCar={carToEdit}
          onClose={() => setCarToEdit(null)}
          t={t} 
          lang={currentLang} 
        />

        <div id="live-market" className="max-w-7xl mx-auto px-4 pb-24">
          <LiveMarketExplorer t={t} lang={currentLang} />
        </div>

        <div id="premium-access" className="bg-slate-100 py-24">
          <div className="max-w-7xl mx-auto px-4">
            <PremiumAuctionViewer t={t} lang={currentLang} />
