             <h2 className="text-3xl md:text-5xl font-black mb-4">{t.reqTitle}</h2>
             <p className="text-slate-400 text-lg mb-16">{t.reqSub}</p>
             <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              {[
                { visa: t.visaPermanent, down: t.terms10, terms: t.months60, icon: '🏆', color: 'bg-yellow-500/20 text-yellow-500' },
                { visa: t.visaWork, down: t.terms20, terms: t.months36, icon: '💼', color: 'bg-blue-500/20 text-blue-500' },
