import React, { useState, useEffect, useRef } from 'react';
import { Car, Language } from '../types';
import { calculateCarLoan } from '../utils/finance';

interface InventoryProps {
  cars: Car[];
  t: any;
  lang: Language;
  onDelete?: (id: string) => void;
  onEdit?: (car: Car) => void;
}

const Inventory: React.FC<InventoryProps> = ({ cars, t, onDelete, onEdit }) => {
  const [selectedCar, setSelectedCar] = useState<Car | null>(null);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const touchStartX = useRef<number | null>(null);

  // Función centralizada para manejar errores de imagen
  const handleImgError = (e: React.SyntheticEvent<HTMLImageElement, Event>) => {
    const target = e.target as HTMLImageElement;
    target.src = 'https://placehold.co/800x600/1e293b/ffffff?text=Imagen+Gaijin+Wheels';
    target.className = target.className + " opacity-50 grayscale";
  };

  const estimateMonthly = (price: number) => {
    const calc = calculateCarLoan({
      carPrice: price,
      downPayment: price * 0.2,
      visaType: 'permanent' as any,
      requestedMonths: 36
    });
    return calc.monthlyPayment;
  };

  const openGallery = (car: Car) => {
    setSelectedCar(car);
    setCurrentImageIndex(0);
    document.body.style.overflow = 'hidden';
  };

  const closeGallery = () => {
    setSelectedCar(null);
    document.body.style.overflow = 'auto';
  };

  const nextImage = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    if (!selectedCar?.gallery) return;
    setCurrentImageIndex((prev) => (prev + 1) % (selectedCar.gallery?.length || 1));
  };

  const prevImage = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    if (!selectedCar?.gallery) return;
    setCurrentImageIndex((prev) => (prev - 1 + (selectedCar.gallery?.length || 1)) % (selectedCar.gallery?.length || 1));
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!selectedCar) return;
      if (e.key === 'ArrowRight') nextImage();
      if (e.key === 'ArrowLeft') prevImage();
      if (e.key === 'Escape') closeGallery();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedCar]);

  const handleTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.touches[0].clientX;
  };

  const handleTouchEnd = (e: React.TouchEvent) => {
    if (touchStartX.current === null) return;
    const touchEndX = e.changedTouches[0].clientX;
    const diff = touchStartX.current - touchEndX;

    if (Math.abs(diff) > 50) {
      if (diff > 0) nextImage();
      else prevImage();
    }
    touchStartX.current = null;
  };

  return (
    <section>
      <div className="text-center mb-12">
        <h2 className="text-3xl md:text-5xl font-black text-slate-900 mb-4">{t.stockTitle}</h2>
        <p className="text-slate-600 text-lg max-w-2xl mx-auto">{t.stockSub}</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {cars.map((car) => (
          <div key={car.id} className="group bg-white rounded-3xl border border-slate-200 overflow-hidden hover:shadow-2xl transition-all duration-500 hover:-translate-y-1 relative">

            <div className="absolute top-4 right-4 z-20 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
              {onEdit && (
                <button 
                  onClick={(e) => { e.stopPropagation(); onEdit(car); }}
                  className="bg-white/90 p-2 rounded-xl text-blue-600 shadow-lg hover:bg-blue-600 hover:text-white transition"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                </button>
              )}
              {onDelete && (
                <button 
                  onClick={(e) => { e.stopPropagation(); onDelete(car.id); }}
                  className="bg-white/90 p-2 rounded-xl text-red-600 shadow-lg hover:bg-red-600 hover:text-white transition"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                </button>
              )}
            </div>

            <div className="relative h-64 overflow-hidden cursor-pointer" onClick={() => openGallery(car)}>
              <img 
                src={car.image} 
                alt={`${car.make} ${car.model}`} 
                className="w-full h-full object-cover group-hover:scale-110 transition duration-700"
                onError={handleImgError}
              />
              <div className="absolute top-4 left-4 bg-red-600 text-white text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-[0.2em]">
                {t.immediateDelivery}
              </div>
              <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                 <div className="bg-white/90 p-3 rounded-full text-slate-900 shadow-xl scale-90 group-hover:scale-100 transition duration-300">
                    <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0zM10 7v3m0 0v3m0-3h3m-3 0H7" /></svg>
                 </div>
              </div>
              <div className="absolute bottom-4 right-4 bg-white/90 backdrop-blur-sm px-4 py-2 rounded-2xl shadow-lg">
                <p className="text-[10px] text-slate-500 uppercase font-bold tracking-wider mb-0.5">{t.startingFrom}</p>
                <p className="text-red-600 font-black text-lg leading-none">
                  ¥{estimateMonthly(car.price).toLocaleString()}<span className="text-xs font-medium text-slate-400 ml-1">{t.perMonth}</span>
                </p>
              </div>
            </div>

            <div className="p-6">
              <div className="flex justify-between items-end mb-6">
                <div>
                  <h3 className="text-2xl font-black text-slate-900 leading-tight">{car.make} {car.model}</h3>
                  <p className="text-slate-400 text-sm">{car.year} • {car.engine}</p>
                </div>
                <div className="text-right">
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Base Price</p>
                  <p className="text-slate-900 font-black text-xl">¥{car.price.toLocaleString()}</p>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4 mb-8">
                <div className="bg-slate-50 p-3 rounded-2xl">
                  <p className="text-[10px] text-slate-400 font-bold uppercase mb-1">Mileage</p>
                  <p className="text-slate-900 font-bold">{car.mileage.toLocaleString()} km</p>
                </div>
                <div className="bg-slate-50 p-3 rounded-2xl">
                  <p className="text-[10px] text-slate-400 font-bold uppercase mb-1">Shaken</p>
                  <p className="text-slate-900 font-bold">{car.shaken}</p>
                </div>
              </div>

              <button onClick={() => openGallery(car)} className="w-full bg-slate-900 hover:bg-red-600 text-white font-bold py-4 rounded-2xl transition-all duration-300 flex items-center justify-center gap-2 group/btn">
                <span>{t.details}</span>
                <svg className="w-4 h-4 group-hover/btn:translate-x-1 transition" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7" />
                </svg>
              </button>
            </div>
          </div>
        ))}
      </div>

      {selectedCar && (
        <div 
          className="fixed inset-0 z-[120] bg-slate-950/98 backdrop-blur-2xl flex flex-col animate-in fade-in duration-200"
          onTouchStart={handleTouchStart}
          onTouchEnd={handleTouchEnd}
        >
           <div className="flex justify-between items-center p-6 text-white z-10">
              <div className="flex items-center gap-4">
                <div className="bg-red-600 w-10 h-10 rounded-xl flex items-center justify-center font-black">GW</div>
                <div>
                  <h3 className="text-xl font-black">{selectedCar.make} {selectedCar.model}</h3>
                  <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest">
                    Imagen {currentImageIndex + 1} de {selectedCar.gallery?.length || 1}
                  </p>
                </div>
              </div>
              <button 
                onClick={closeGallery}
                className="bg-white/10 hover:bg-red-600 p-4 rounded-full transition-all duration-300 group"
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
           </div>

           <div className="flex-1 relative flex items-center justify-center px-2 sm:px-12 py-4">
              <button onClick={prevImage} className="hidden sm:flex absolute left-8 z-10 bg-white/5 hover:bg-red-600 text-white p-6 rounded-full transition-all duration-300 backdrop-blur-md border border-white/10">
                <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M15 19l-7-7 7-7" /></svg>
              </button>

              <div className="w-full h-full flex items-center justify-center p-4">
                 <img 
                    key={currentImageIndex}
                    src={selectedCar.gallery ? selectedCar.gallery[currentImageIndex] : selectedCar.image} 
                    className="max-h-full max-w-full object-contain rounded-xl shadow-2xl animate-in zoom-in-95 slide-in-from-right-10 duration-500 cursor-zoom-out"
                    alt="Car Detail"
                    onClick={closeGallery}
                    onError={handleImgError}
                 />
              </div>

              <button onClick={nextImage} className="hidden sm:flex absolute right-8 z-10 bg-white/5 hover:bg-red-600 text-white p-6 rounded-full transition-all duration-300 backdrop-blur-md border border-white/10">
                <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7" /></svg>
              </button>
           </div>

           <div className="p-8 bg-black/20 backdrop-blur-sm border-t border-white/5 flex justify-center gap-3 overflow-x-auto pb-12 sm:pb-8 custom-scrollbar">
              {selectedCar.gallery?.map((img, idx) => (
                <button 
                  key={idx}
                  onClick={() => setCurrentImageIndex(idx)}
                  className={`w-16 h-16 sm:w-24 sm:h-24 rounded-2xl overflow-hidden border-4 transition-all duration-300 shrink-0 ${currentImageIndex === idx ? 'border-red-600 scale-110 shadow-lg' : 'border-transparent opacity-40 hover:opacity-100'}`}
                >
                  <img src={img} className="w-full h-full object-cover" alt={`Thumb ${idx}`} onError={handleImgError} />
                </button>
              ))}
           </div>
        </div>
      )}
    </section>
  );
};

export default Inventory;

import React, { useState, useEffect } from 'react';
import { Car, Language } from '../types';

interface AdminPanelProps {
  onAddCar: (car: Car) => void;
  onEditCar: (car: Car) => void;
  editingCar?: Car | null;
  onClose?: () => void;
  t: any;
  lang: Language;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onAddCar, onEditCar, editingCar, onClose, t }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [bulkLinks, setBulkLinks] = useState('');
  const [formData, setFormData] = useState({
    make: '',
    model: '',
    year: new Date().getFullYear(),
    mileage: '',
    price: '',
    engine: '660cc',
    shaken: '',
    transmission: 'AT' as 'AT' | 'MT'
  });
  const [images, setImages] = useState<string[]>([]);

  useEffect(() => {
    if (editingCar) {
      setFormData({
        make: editingCar.make,
        model: editingCar.model,
        year: editingCar.year,
        mileage: String(editingCar.mileage),
        price: String(editingCar.price),
        engine: editingCar.engine,
        shaken: editingCar.shaken,
        transmission: editingCar.transmission
      });
      setImages(editingCar.gallery || [editingCar.image]);
      setIsOpen(true);
    }
  }, [editingCar]);

  const handleClose = () => {
    setIsOpen(false);
    if (onClose) onClose();
    setTimeout(() => {
      resetForm();
    }, 300);
  };

  const resetForm = () => {
    setFormData({ make: '', model: '', year: new Date().getFullYear(), mileage: '', price: '', engine: '660cc', shaken: '', transmission: 'AT' });
    setImages([]);
    setBulkLinks('');
  };

  const setAsCover = (index: number) => {
    const newImages = [...images];
    const [selectedImage] = newImages.splice(index, 1);
    newImages.unshift(selectedImage);
    setImages(newImages);
  };

  const processBulkLinks = () => {
    if (!bulkLinks.trim()) return;

    if (bulkLinks.includes('/drive/folders/') && !bulkLinks.includes('file/d/')) {
      alert("⚠️ Has pegado un enlace de CARPETA. \n\nPara que funcione: Entra a la carpeta en Drive, selecciona todas las fotos, haz clic derecho -> Compartir -> Copiar enlaces, y pega ESO aquí.");
      return;
    }

    const driveIdRegex = /(?:file\/d\/|id=)([a-zA-Z0-9_-]{25,})[/?]?/g;
    let match;
    const foundIds: string[] = [];

    while ((match = driveIdRegex.exec(bulkLinks)) !== null) {
      if (match[1]) {
        // Usamos el endpoint de 'uc' para visualización directa que es más compatible
        foundIds.push(`https://drive.google.com/thumbnail?id=${match[1]}&sz=w1200`);
      }
    }

    if (foundIds.length > 0) {
      const uniqueNewLinks = foundIds.filter(link => !images.includes(link));
      setImages(prev => [...prev, ...uniqueNewLinks]);
      setBulkLinks('');
    } else {
      alert("No se detectaron IDs de fotos válidos. Asegúrate de que los enlaces sean de ARCHIVOS compartidos públicamente.");
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      setLoading(true);
      const files = Array.from(e.target.files) as File[];
      const base64Promises = files.map(file => {
        return new Promise<string>((resolve) => {
          const reader = new FileReader();
          reader.onloadend = () => resolve(reader.result as string);
          reader.readAsDataURL(file);
        });
      });
      const base64Images = await Promise.all(base64Promises);
      setImages(prev => [...prev, ...base64Images]);
      setLoading(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (images.length === 0) return alert("Carga al menos una foto");

    const carData: Car = {
      id: editingCar ? editingCar.id : `custom-${Date.now()}`,
      make: formData.make,
      model: formData.model,
      year: Number(formData.year),
      mileage: Number(formData.mileage),
      price: Number(formData.price),
      image: images[0],
      gallery: images,
      transmission: formData.transmission,
      engine: formData.engine,
      shaken: formData.shaken
    };

    if (editingCar) {
      onEditCar(carData);
    } else {
      onAddCar(carData);
    }

    handleClose();
  };

  return (
    <>
      <button 
        onClick={() => { resetForm(); setIsOpen(true); }}
        className="fixed bottom-6 left-6 z-50 bg-slate-900 text-white p-4 rounded-full shadow-2xl hover:bg-red-600 transition-all border border-slate-700 flex items-center gap-2 group"
      >
        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
        <span className="max-w-0 overflow-hidden group-hover:max-w-xs transition-all duration-500 font-bold whitespace-nowrap uppercase tracking-widest text-[10px]">Nueva Unidad</span>
      </button>

      {isOpen && (
        <div className="fixed inset-0 z-[200] bg-slate-900/95 backdrop-blur-md flex items-center justify-center p-4 animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-2xl rounded-[3rem] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50">
              <div>
                <h2 className="text-2xl font-black text-slate-900 italic tracking-tighter uppercase">
                  {editingCar ? 'Editar Unidad' : 'Gaijin Editor'}
                </h2>
                <p className="text-slate-500 text-xs font-bold uppercase tracking-widest mt-1">
                  {editingCar ? `Modificando ID: ${editingCar.id}` : 'Configuración de Inventario'}
                </p>
              </div>
              <button onClick={handleClose} className="bg-white p-2 rounded-full shadow-sm hover:text-red-600 transition">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-8 overflow-y-auto space-y-8 scrollbar-hide">
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Marca</label>
                    <input required value={formData.make} onChange={e => setFormData({...formData, make: e.target.value})} className="w-full bg-slate-100 p-4 rounded-2xl outline-none focus:ring-2 focus:ring-red-600/20 font-bold" placeholder="Toyota" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Modelo</label>
                    <input required value={formData.model} onChange={e => setFormData({...formData, model: e.target.value})} className="w-full bg-slate-100 p-4 rounded-2xl outline-none focus:ring-2 focus:ring-red-600/20 font-bold" placeholder="Prius" />
                  </div>
                </div>

                <div className="grid grid-cols-3 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Año</label>
                    <input type="number" required value={formData.year} onChange={e => setFormData({...formData, year: Number(e.target.value)})} className="w-full bg-slate-100 p-4 rounded-2xl outline-none font-bold" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Precio</label>
                    <input type="number" required value={formData.price} onChange={e => setFormData({...formData, price: e.target.value})} className="w-full bg-slate-100 p-4 rounded-2xl outline-none font-bold text-red-600" placeholder="780000" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Kms</label>
                    <input type="number" required value={formData.mileage} onChange={e => setFormData({...formData, mileage: e.target.value})} className="w-full bg-slate-100 p-4 rounded-2xl outline-none font-bold" placeholder="58000" />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Motor</label>
                    <input required value={formData.engine} onChange={e => setFormData({...formData, engine: e.target.value})} className="w-full bg-slate-100 p-4 rounded-2xl outline-none focus:ring-2 focus:ring-red-600/20 font-bold" placeholder="1.8L Hybrid" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Shaken Hasta</label>
                    <input required value={formData.shaken} onChange={e => setFormData({...formData, shaken: e.target.value})} className="w-full bg-slate-100 p-4 rounded-2xl outline-none focus:ring-2 focus:ring-red-600/20 font-bold" placeholder="2025/10" />
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <label className="bg-slate-50 border-2 border-dashed border-slate-200 p-6 rounded-[2rem] flex flex-col items-center justify-center gap-2 cursor-pointer hover:bg-slate-100 transition group">
                  <input type="file" multiple accept="image/*" onChange={handleFileChange} className="hidden" />
                  <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center shadow-sm group-hover:scale-110 transition">
                    <svg className="w-5 h-5 text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                  </div>
                  <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Añadir Locales</span>
                </label>

                <div className="bg-blue-50/50 border-2 border-blue-100 p-6 rounded-[2rem] flex flex-col gap-3">
                  <textarea 
                    value={bulkLinks}
                    onChange={e => setBulkLinks(e.target.value)}
                    className="w-full bg-white border border-blue-100 p-3 rounded-xl outline-none text-[10px] font-mono h-16 placeholder:text-blue-200 resize-none"
                    placeholder="Pega links de Drive aquí..."
                  />
                  <button type="button" onClick={processBulkLinks} className="w-full bg-blue-600 text-white py-2 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-blue-700 transition">
                    Extraer de Drive
                  </button>
                </div>
              </div>

              <div className="space-y-4">
                <div className="flex justify-between items-center">
                   <h3 className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Gestión de Galería ({images.length})</h3>
                   {images.length > 1 && <p className="text-[9px] text-slate-400 font-bold italic">Selecciona la ⭐ para elegir portada</p>}
                </div>

                <div className="grid grid-cols-3 sm:grid-cols-4 gap-3">
                  {images.map((img, i) => (
                    <div key={i} className={`aspect-square rounded-[1.5rem] overflow-hidden relative group transition-all duration-300 ${i === 0 ? 'ring-4 ring-yellow-400 ring-offset-2' : 'border border-slate-200 opacity-80 hover:opacity-100'}`}>
                      <img 
                        src={img} 
                        className="w-full h-full object-cover" 
                        onError={(e) => { (e.target as HTMLImageElement).src = 'https://placehold.co/400x400/ef4444/ffffff?text=Link+Inv%C3%A1lido'; }}
                      />

                      {i === 0 && (
                        <div className="absolute top-2 left-2 bg-yellow-400 text-slate-900 text-[8px] font-black px-2 py-0.5 rounded-full shadow-lg z-10 flex items-center gap-1 uppercase tracking-tighter">
                          <svg className="w-2.5 h-2.5" fill="currentColor" viewBox="0 0 20 20"><path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" /></svg>
