import React, { useState, useEffect } from 'react';
import { Car, Language } from '../types';

interface AdminPanelProps {
  onAddCar: (car: Car) => void;
  onEditCar: (car: Car) => void;
  editingCar?: Car | null;
  onClose?: () => void;
  t: any;
  lang: Language;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onAddCar, onEditCar, editingCar, onClose, t }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [bulkLinks, setBulkLinks] = useState('');
  const [formData, setFormData] = useState({
    make: '',
    model: '',
    year: new Date().getFullYear(),
    mileage: '',
    price: '',
    engine: '660cc',
    shaken: '',
    transmission: 'AT' as 'AT' | 'MT',
    customDownPayment: '',
    customMonths: ''
  });
  const [images, setImages] = useState<string[]>([]);

  useEffect(() => {
    if (editingCar) {
      setFormData({
        make: editingCar.make,
        model: editingCar.model,
        year: editingCar.year,
        mileage: String(editingCar.mileage),
        price: String(editingCar.price),
        engine: editingCar.engine,
        shaken: editingCar.shaken,
        transmission: editingCar.transmission,
        customDownPayment: editingCar.customDownPayment ? String(editingCar.customDownPayment) : '',
        customMonths: editingCar.customMonths ? String(editingCar.customMonths) : ''
      });
      setImages(editingCar.gallery || [editingCar.image]);
      setIsOpen(true);
    }
  }, [editingCar]);

  const handleClose = () => {
    setIsOpen(false);
    if (onClose) onClose();
    setTimeout(() => {
      resetForm();
    }, 300);
  };

  const resetForm = () => {
    setFormData({ 
      make: '', model: '', year: new Date().getFullYear(), mileage: '', price: '', 
      engine: '660cc', shaken: '', transmission: 'AT', customDownPayment: '', customMonths: '' 
    });
    setImages([]);
    setBulkLinks('');
  };

  const setAsCover = (index: number) => {
    const newImages = [...images];
    const [selectedImage] = newImages.splice(index, 1);
    newImages.unshift(selectedImage);
    setImages(newImages);
  };

  const processBulkLinks = () => {
    if (!bulkLinks.trim()) return;

    if (bulkLinks.includes('/drive/folders/') && !bulkLinks.includes('file/d/')) {
      alert("⚠️ Has pegado un enlace de CARPETA. \n\nPara que funcione: Entra a la carpeta en Drive, selecciona todas las fotos, haz clic derecho -> Compartir -> Copiar enlaces, y pega ESO aquí.");
      return;
    }

    const driveIdRegex = /(?:file\/d\/|id=)([a-zA-Z0-9_-]{25,})[/?]?/g;
    let match;
    const foundIds: string[] = [];

    while ((match = driveIdRegex.exec(bulkLinks)) !== null) {
      if (match[1]) {
        foundIds.push(`https://drive.google.com/thumbnail?id=${match[1]}&sz=w1200`);
      }
    }

    if (foundIds.length > 0) {
      const uniqueNewLinks = foundIds.filter(link => !images.includes(link));
      setImages(prev => [...prev, ...uniqueNewLinks]);
      setBulkLinks('');
    } else {
      alert("No se detectaron IDs de fotos válidos.");
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      setLoading(true);
      const files = Array.from(e.target.files) as File[];
      const base64Promises = files.map(file => {
        return new Promise<string>((resolve) => {
          const reader = new FileReader();
          reader.onloadend = () => resolve(reader.result as string);
          reader.readAsDataURL(file);
        });
      });
      const base64Images = await Promise.all(base64Promises);
      setImages(prev => [...prev, ...base64Images]);
      setLoading(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (images.length === 0) return alert("Carga al menos una foto");

    const carData: Car = {
      id: editingCar ? editingCar.id : `custom-${Date.now()}`,
      make: formData.make,
      model: formData.model,
