              </div>
              <button onClick={handleClose} className="bg-white p-2 rounded-full shadow-sm hover:text-red-600 transition">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-8 overflow-y-auto space-y-8 scrollbar-hide">
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Marca</label>
                    <input required value={formData.make} onChange={e => setFormData({...formData, make: e.target.value})} className="w-full bg-slate-100 p-4 rounded-2xl outline-none focus:ring-2 focus:ring-red-600/20 font-bold" placeholder="Toyota" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Modelo</label>
                    <input required value={formData.model} onChange={e => setFormData({...formData, model: e.target.value})} className="w-full bg-slate-100 p-4 rounded-2xl outline-none focus:ring-2 focus:ring-red-600/20 font-bold" placeholder="Prius" />
                  </div>
