import React, { useState, useEffect, useRef } from 'react';
import { Car, Language } from '../types';
import { calculateCarLoan } from '../utils/finance';

interface InventoryProps {
  cars: Car[];
  t: any;
  lang: Language;
  onDelete?: (id: string) => void;
  onEdit?: (car: Car) => void;
}

const Inventory: React.FC<InventoryProps> = ({ cars, t, onDelete, onEdit }) => {
  const [selectedCar, setSelectedCar] = useState<Car | null>(null);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const touchStartX = useRef<number | null>(null);

  // Función centralizada para manejar errores de imagen
  const handleImgError = (e: React.SyntheticEvent<HTMLImageElement, Event>) => {
    const target = e.target as HTMLImageElement;
    target.src = 'https://placehold.co/800x600/1e293b/ffffff?text=Imagen+Gaijin+Wheels';
    target.className = target.className + " opacity-50 grayscale";
  };

  const estimateMonthly = (car: Car) => {
    // Si el auto tiene configurado financiamiento personalizado, lo usamos.
    // Si no, usamos el cálculo por defecto (20% inicial, 36 meses).
    const calc = calculateCarLoan({
      carPrice: car.price,
      downPayment: car.customDownPayment !== undefined ? car.customDownPayment : car.price * 0.2,
      visaType: 'permanent' as any,
      requestedMonths: car.customMonths !== undefined ? car.customMonths : 36
    });
    return calc.monthlyPayment;
  };

  const openGallery = (car: Car) => {
    setSelectedCar(car);
    setCurrentImageIndex(0);
    document.body.style.overflow = 'hidden';
  };

  const closeGallery = () => {
    setSelectedCar(null);
    document.body.style.overflow = 'auto';
  };

  const nextImage = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    if (!selectedCar?.gallery) return;
    setCurrentImageIndex((prev) => (prev + 1) % (selectedCar.gallery?.length || 1));
  };

  const prevImage = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    if (!selectedCar?.gallery) return;
    setCurrentImageIndex((prev) => (prev - 1 + (selectedCar.gallery?.length || 1)) % (selectedCar.gallery?.length || 1));
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!selectedCar) return;
      if (e.key === 'ArrowRight') nextImage();
      if (e.key === 'ArrowLeft') prevImage();
      if (e.key === 'Escape') closeGallery();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedCar]);

  const handleTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.touches[0].clientX;
  };

  const handleTouchEnd = (e: React.TouchEvent) => {
    if (touchStartX.current === null) return;
    const touchEndX = e.changedTouches[0].clientX;
    const diff = touchStartX.current - touchEndX;

    if (Math.abs(diff) > 50) {
      if (diff > 0) nextImage();
      else prevImage();
    }
    touchStartX.current = null;
  };

  return (
    <section>
      <div className="text-center mb-12">
        <h2 className="text-3xl md:text-5xl font-black text-slate-900 mb-4">{t.stockTitle}</h2>
        <p className="text-slate-600 text-lg max-w-2xl mx-auto">{t.stockSub}</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {cars.map((car) => (
          <div key={car.id} className="group bg-white rounded-3xl border border-slate-200 overflow-hidden hover:shadow-2xl transition-all duration-500 hover:-translate-y-1 relative">

            <div className="absolute top-4 right-4 z-20 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
              {onEdit && (
                <button 
                  onClick={(e) => { e.stopPropagation(); onEdit(car); }}
